INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines CRM-Systems für Marketing entscheidend?', 2, '[{"text": "Kampagnenmanagement", "correct": true, "because": "Steuert Marketingaktionen"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein CRM-System ohne mobile App für Außendienstmitarbeiter geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Mobiler Zugriff ist essenziell"}, {"text": "Ja", "correct": false, "because": "Eingeschränkte Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für ein CRM-System wichtig?', 5, '[{"text": "Kundendatenverwaltung", "correct": true, "because": "Zentralisiert Kundeninformationen"}, {"text": "Vertriebsunterstützung", "correct": true, "because": "Fördert Verkaufsprozesse"}, {"text": "Installationsgröße", "correct": false, "because": "Kein funktionaler Faktor"}, {"text": "Integration mit E-Mail", "correct": true, "because": "Verbessert Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über CRM-Systeme richtig? a) Sie sind nur für große Unternehmen. b) Sie speichern Kundeninteraktionen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Auch für kleine Firmen geeignet"}, {"text": "Nur b) stimmt", "correct": true, "because": "Interaktionen sind Kernfunktion"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines CRM-Systems für den Kundenservice ignorieren?', 2, '[{"text": "Ticket-System", "correct": false, "because": "Wichtig für Support"}, {"text": "Optisches Design", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Berichtsfunktionen", "correct": false, "because": "Hilft bei Analyse"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines CRM-Systems für den Vertrieb entscheidend?', 2, '[{"text": "Kundeninteraktionsverfolgung", "correct": true, "because": "Optimiert Vertriebsprozesse"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein CRM-System nur für große Unternehmen geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Auch kleine Firmen profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierbare Lösungen verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Effektivität eines CRM-Systems wichtig?', 5, '[{"text": "Kundendatenverwaltung", "correct": true, "because": "Zentralisiert Informationen"}, {"text": "Analysefunktionen", "correct": true, "because": "Liefert Verkaufseinblicke"}, {"text": "Installationsgröße", "correct": false, "because": "Kein Einfluss auf Effektivität"}, {"text": "Integration mit anderen Systemen", "correct": true, "because": "Verbessert Datenfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über CRM-Systeme richtig? a) Sie verbessern die Kundenbindung. b) Sie ersetzen ERP-Systeme vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kundenbindung ist Hauptziel"}, {"text": "Beides stimmt", "correct": false, "because": "CRM und ERP ergänzen sich"}, {"text": "Nur b) stimmt", "correct": false, "because": "ERP hat andere Schwerpunkte"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines CRM-Systems für ein kleines Team ignorieren?', 2, '[{"text": "Benutzerfreundlichkeit", "correct": false, "because": "Wichtig für Akzeptanz"}, {"text": "Optisches Design", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Skalierbarkeit", "correct": false, "because": "Relevant für Wachstum"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines CRM-Systems für den Vertrieb entscheidend?', 2, '[{"text": "Kundeninteraktionsverfolgung", "correct": true, "because": "Optimiert Verkaufsprozesse"}, {"text": "Farbe der Oberfläche", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein CRM-System ohne Cloud-Anbindung für ein verteiltes Team geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Cloud erleichtert Zugriff von überall"}, {"text": "Ja", "correct": false, "because": "Eingeschränkte Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines CRM-Systems wichtig?', 5, '[{"text": "Datenintegration", "correct": true, "because": "Verknüpft Kundendaten"}, {"text": "Benutzerfreundlichkeit", "correct": true, "because": "Erleichtert Nutzung"}, {"text": "Installationsgröße", "correct": false, "because": "Kein Leistungsfaktor"}, {"text": "Automatisierungsfunktionen", "correct": true, "because": "Spart Zeit bei Prozessen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über CRM-Systeme richtig? a) Sie dienen nur dem Marketing. b) Sie speichern Kundeninteraktionen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "CRM ist breiter gefächert"}, {"text": "Nur b) stimmt", "correct": true, "because": "Interaktionen sind Kernfunktion"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht nur Marketing"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines CRM-Systems für ein kleines Unternehmen ignorieren?', 2, '[{"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Optisches Design", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Kosten", "correct": false, "because": "Entscheidend für Budget"}]');
